package com.myaaptha.domain.finance;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
class FinanceServiceTest{FinancialTransactionRepository repo;FinanceService service;@BeforeEach void setup(){repo=mock(FinancialTransactionRepository.class);service=new FinanceService(repo);when(repo.findByUserIdAndSourceFingerprint(anyLong(),anyString())).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(x->{FinancialTransactionEntity e=x.getArgument(0);try{var f=FinancialTransactionEntity.class.getDeclaredField("id");f.setAccessible(true);f.set(e,7L);}catch(Exception ex){throw new RuntimeException(ex);}return e;});}
 @Test void parsesAndCategorizesIndianTransactionSms(){var result=service.add(1L,new FinanceService.Input(null,null,null,null,null,Instant.parse("2026-08-01T10:00:00Z"),"SMS","Rs. 1,249.50 debited from A/c at APOLLO PHARMACY","HDFCBK"));assertThat(result.amount()).isEqualByComparingTo("1249.50");assertThat(result.direction()).isEqualTo("EXPENSE");assertThat(result.category()).isEqualTo("HEALTH");assertThat(result.source()).isEqualTo("SMS");}
 @Test void summarizesOnlyRepositoryResultsForRequestedUserAndMonth(){FinancialTransactionEntity expense=entity(1L,"250","EXPENSE","GROCERIES"),income=entity(1L,"1000","INCOME","INCOME");when(repo.findByUserIdAndOccurredAtBetweenOrderByOccurredAtDesc(eq(1L),any(),any())).thenReturn(List.of(expense,income));var result=service.summary(1L,YearMonth.of(2026,8));assertThat(result.spending()).isEqualByComparingTo("250");assertThat(result.income()).isEqualByComparingTo("1000");assertThat(result.categories()).containsEntry("GROCERIES",new BigDecimal("250"));}
 @Test void rejectsSmsWithoutCurrencyAmount(){assertThatThrownBy(()->service.add(1L,new FinanceService.Input(null,null,null,null,null,Instant.now(),"SMS","Your statement is ready","BANK"))).hasMessageContaining("No INR amount");}
 private FinancialTransactionEntity entity(Long user,String amount,String direction,String category){var e=new FinancialTransactionEntity();e.setUserId(user);e.setAmount(new BigDecimal(amount));e.setDirection(direction);e.setCategory(category);e.setOccurredAt(Instant.now());e.setSource("MANUAL");return e;}}
